package com.rpgate.service;
import com.rpgate.dto.PersonnelDtos; import com.rpgate.repository.PersonnelRepository; import org.springframework.stereotype.Service; import java.util.List;
@Service public class PersonnelService { private final PersonnelRepository repo; public PersonnelService(PersonnelRepository repo){this.repo=repo;} public List<PersonnelDtos.Response> list(String q){return repo.list(q);} public PersonnelDtos.Response get(long id){return repo.get(id);} public PersonnelDtos.Response getOrThrow(long id){var value=repo.get(id);if(value==null)throw new IllegalArgumentException("Personnel not found");return value;} public PersonnelDtos.Response findByArmyOrCard(String armyNo,String cardNo){return repo.findByArmyOrCard(armyNo,cardNo);} public PersonnelDtos.Response create(PersonnelDtos.Request x){return repo.get(repo.insert(x));} public PersonnelDtos.Response update(long id,PersonnelDtos.Request x){getOrThrow(id);repo.update(id,x);return repo.get(id);} public void delete(long id){if(repo.delete(id)==0)throw new IllegalArgumentException("Personnel not found");} public void clear(){repo.clear();} }
